                  const SizedBox(height: 20),

                  SizedBox(
                    width: double.infinity,
                    child: ElevatedButton(
                      onPressed: () {
                        final name = nameCtrl.text.trim();
                        if (name.isEmpty) return;
                        final sets = (int.tryParse(setsCtrl.text) ?? 3).clamp(
                          1,
                          20,
                        );
                        final repsList = repsCtrls
                            .map((c) => int.tryParse(c.text) ?? 10)
                            .toList();
                        final recovery = int.tryParse(recoveryCtrl.text) ?? 90;
                        final pausa = int.tryParse(pausaCtrl.text) ?? 120;
                        final ex = ExerciseConfig(
                          name: name,
                          targetSets: sets,
                          repsList: repsList,
                          recoveryTime: recovery,
                          interExercisePause: pausa,
                          notePT: noteCtrl.text.trim(),
                          noteCliente: '',
                          supersetGroup: supersetGroup,
                          gifFilename: selectedExInfo?.gifFilename,
                        );
                        Navigator.pop(c);
                        setState(() => _days[dayIdx].exercises.add(ex));
                        _save();
                      },
                      child: Text(
                        AppL.save,
                        style: const TextStyle(
                          fontWeight: FontWeight.bold,
                          fontSize: 16,
                        ),
                      ),
                    ),
                  ),
                ],
              ),
            ),
          );
        },
      ),
    );
  }

  void _apriArchivioEsercizi(
    BuildContext context,
    StateSetter setS,
    Function(ExerciseInfo) onSelect,
  ) {
    String? selectedCategory;
    String searchQuery = '';

    showModalBottomSheet(
      context: context,
      backgroundColor: _isDarkCtx(context) ? const Color(0xFF1C1C1E) : Colors.white,
      isScrollControlled: true,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(20)),
      ),
      builder: (c) => StatefulBuilder(
        builder: (ctx, setA) {
          final cats =
              kGifCatalog
                  .map((e) => e.category)
                  .toSet()
                  .where((c) => c.isNotEmpty && c != 'altro')
                  .toList()
                ..sort();

          List<ExerciseInfo> filtered = selectedCategory != null
              ? kGifCatalog
                    .where(
                      (e) => exerciseAllCategories(e).contains(selectedCategory),
                    )
                    .toList()
              : kGifCatalog.where((e) => e.category != 'altro').toList();

          if (searchQuery.isNotEmpty) {
            final q = searchQuery.toLowerCase();
            filtered = filtered
                .where(
                  (e) =>
                      e.name.toLowerCase().contains(q) ||
                      e.nameEn.toLowerCase().contains(q) ||
                      e.aliases.any((a) => a.toLowerCase().contains(q)),
                )
                .toList();
          }

          return Container(
            height: MediaQuery.of(ctx).size.height * 0.85,
            padding: const EdgeInsets.fromLTRB(16, 12, 16, 0),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Center(
                  child: Container(
                    width: 40,
                    height: 4,
                    margin: const EdgeInsets.only(bottom: 12),
                    decoration: BoxDecoration(
                      color: _isDarkCtx(context) ? Colors.white24 : Colors.black26,
                      borderRadius: BorderRadius.circular(2),
                    ),
                  ),
                ),
                TextField(
                  style: TextStyle(color: _isDarkCtx(context) ? Colors.white : Colors.black87),
                  decoration: InputDecoration(
                    hintText: AppL.searchExerciseHint,
                    hintStyle: TextStyle(color: _isDarkCtx(context) ? Colors.white38 : Colors.black38),
                    prefixIcon: Icon(Icons.search, color: _isDarkCtx(context) ? Colors.white38 : Colors.black38),
                    filled: true,
                    fillColor: Colors.white10,
                    border: OutlineInputBorder(
                      borderRadius: BorderRadius.circular(12),
                      borderSide: BorderSide.none,
                    ),
                    contentPadding: const EdgeInsets.symmetric(
                      horizontal: 12,
                      vertical: 10,
                    ),
                  ),
                  onChanged: (v) => setA(() => searchQuery = v),
                ),
                const SizedBox(height: 10),
                SingleChildScrollView(
                  scrollDirection: Axis.horizontal,
                  child: Row(
                    children: [
                      _archiveChip(
                        label: AppL.all,
                        selected: selectedCategory == null,
                        onTap: () => setA(() => selectedCategory = null),
                        accent: appAccentNotifier.value,
                      ),
                      ...cats.map(
                        (cat) => _archiveChip(
                          label:
                              '${kBodyPartIcons[cat] ?? ''} ${bodyPartName(cat)}',
                          selected: selectedCategory == cat,
                          onTap: () => setA(() => selectedCategory = cat),
                          accent: appAccentNotifier.value,
                        ),
                      ),
                    ],
                  ),
                ),
                const SizedBox(height: 10),
                Expanded(
                  child: GridView.builder(
                    gridDelegate:
                        const SliverGridDelegateWithFixedCrossAxisCount(
                          crossAxisCount: 2,
                          childAspectRatio: 0.85,
                          mainAxisSpacing: 8,
                          crossAxisSpacing: 8,
                        ),
                    itemCount: filtered.length,
                    itemBuilder: (_, i) {
                      final ex = filtered[i];
                      return GestureDetector(
                        onTap: () {
                          Navigator.pop(c);
                          setS(() => onSelect(ex));
                        },
                        child: Container(
                          decoration: BoxDecoration(
                            color: _isDarkCtx(context) ? Colors.white10 : Colors.grey.shade100,
                            borderRadius: BorderRadius.circular(12),
                          ),
                          child: Column(
                            children: [
                              Expanded(
                                child: ClipRRect(
                                  borderRadius: const BorderRadius.vertical(
                                    top: Radius.circular(12),
                                  ),
                                  child: ex.gifFilename != null
                                      ? Image.asset(
                                          exerciseAnimationAssetPath(
                                            ex.gifFilename!,
                                          ),
                                          fit: BoxFit.cover,
                                          width: double.infinity,
                                          errorBuilder: (_, __, ___) =>
                                              const Center(
                                                child: Icon(
                                                  Icons.fitness_center,
                                                  color: Colors.white30,
                                                  size: 32,
                                                ),
                                              ),
                                        )
                                      : const Center(
                                          child: Icon(
                                            Icons.fitness_center,
                                            color: Colors.white30,
                                            size: 32,
                                          ),
                                        ),
                                ),
                              ),
                              Padding(
                                padding: const EdgeInsets.all(6),
                                child: Text(
                                  ex.name,
                                  style: TextStyle(
                                    color: _isDarkCtx(context) ? Colors.white : Colors.black87,
                                    fontSize: 11,
                                    fontWeight: FontWeight.w500,
                                  ),
                                  maxLines: 2,
                                  overflow: TextOverflow.ellipsis,
                                  textAlign: TextAlign.center,
                                ),
                              ),
                            ],
                          ),
                        ),
                      );
                    },
                  ),
                ),
              ],
            ),
          );
        },
      ),
    );
  }

  Widget _archiveChip({
    required String label,
    required bool selected,
    required VoidCallback onTap,
    required Color accent,
  }) {
    return GestureDetector(
      onTap: onTap,
      child: Container(
        margin: const EdgeInsets.only(right: 8),
        padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 6),
        decoration: BoxDecoration(
          color: selected ? accent.withAlpha(40) : Colors.white10,
          borderRadius: BorderRadius.circular(20),
          border: Border.all(
            color: selected ? accent : Colors.white24,
            width: selected ? 1.5 : 1,
          ),
        ),
        child: Text(
          label,
          style: TextStyle(
            color: selected ? accent : Colors.white60,
            fontSize: 12,
            fontWeight: selected ? FontWeight.bold : FontWeight.normal,
          ),
        ),
      ),
    );
  }

  void _eliminaEsercizio(int dayIdx, int exIdx) {
    setState(() => _days[dayIdx].exercises.removeAt(exIdx));
    _save();
  }

  void _riordinaGiorni(int oldIndex, int newIndex) {
    if (newIndex > oldIndex) newIndex -= 1;
    setState(() {
      final day = _days.removeAt(oldIndex);
      _days.insert(newIndex, day);
    });
    _save();
  }

  void _riordinaEsercizi(int dayIdx, int oldIndex, int newIndex) {
    if (newIndex > oldIndex) newIndex -= 1;
    setState(() {
      final ex = _days[dayIdx].exercises.removeAt(oldIndex);
      _days[dayIdx].exercises.insert(newIndex, ex);
    });
    _save();
  }

  void _rinominaGiorno(int dayIdx) {
    final ctrl = TextEditingController(text: _days[dayIdx].dayName);
    showDialog(
      context: context,
      builder: (_) => AlertDialog(
        backgroundColor: _isDarkCtx(context) ? const Color(0xFF1C1C1E) : Colors.white,
        title: Text(
          AppL.renameSession,
          style: TextStyle(color: _isDarkCtx(context) ? Colors.white : Colors.black87),
        ),
        content: TextField(
          controller: ctrl,
          autofocus: true,
          style: TextStyle(color: _isDarkCtx(context) ? Colors.white : Colors.black87),
          decoration: InputDecoration(
            labelText: AppL.sessionName,
            labelStyle: TextStyle(color: _isDarkCtx(context) ? Colors.white54 : Colors.black54),
            filled: true,
            fillColor: Colors.black26,
            border: OutlineInputBorder(
              borderRadius: BorderRadius.circular(12),
              borderSide: BorderSide.none,
            ),
          ),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(context),
            child: Text(AppL.cancel),
          ),
          TextButton(
            onPressed: () {
              final name = ctrl.text.trim();
              if (name.isEmpty) return;
              setState(() => _days[dayIdx].dayName = _limitToOneEmoji(name));
              _save();
              Navigator.pop(context);
            },
            child: Text(
              AppL.save,
              style: TextStyle(
                color: appAccentNotifier.value,
                fontWeight: FontWeight.bold,
              ),
            ),
          ),
        ],
      ),
    );
  }

  void _modificaEsercizio(int dayIdx, int exIdx) {
    final orig = _days[dayIdx].exercises[exIdx];
    final accent = appAccentNotifier.value;
    final nameCtrl = TextEditingController(text: orig.name);
    final setsCtrl = TextEditingController(text: '${orig.targetSets}');
    final recoveryCtrl = TextEditingController(text: '${orig.recoveryTime}');
    final pausaCtrl = TextEditingController(text: '${orig.interExercisePause}');
    final noteCtrl = TextEditingController(text: orig.notePT);
    int supersetGroup = orig.supersetGroup;
    int currentSets = orig.targetSets;
    List<TextEditingController> repsCtrls = List.generate(
      orig.repsList.length,
      (i) => TextEditingController(text: '${orig.repsList[i]}'),
    );
    if (repsCtrls.isEmpty) repsCtrls = [TextEditingController(text: '10')];
    ExerciseInfo? selectedExInfo;

    showModalBottomSheet(
      context: context,
      isScrollControlled: true,
      backgroundColor: _isDarkCtx(context) ? const Color(0xFF1C1C1E) : Colors.white,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(20)),
      ),
      builder: (c) => StatefulBuilder(
        builder: (ctx, setS) {
          void updateSets(String val) {
            final n = (int.tryParse(val) ?? 1).clamp(1, 20);
            setS(() {
              currentSets = n;
              while (repsCtrls.length < n) {
                repsCtrls.add(
                  TextEditingController(
                    text: repsCtrls.isNotEmpty ? repsCtrls.last.text : '10',
                  ),
                );
              }
              while (repsCtrls.length > n) {
                repsCtrls.last.dispose();
                repsCtrls.removeLast();
              }
            });
          }

          return Padding(
            padding: EdgeInsets.only(
              bottom: MediaQuery.of(ctx).viewInsets.bottom,
            ),
            child: DraggableScrollableSheet(
              initialChildSize: 0.9,
              minChildSize: 0.5,
              maxChildSize: 0.95,
              expand: false,
              builder: (_, scrollCtrl) => ListView(
                controller: scrollCtrl,
                padding: const EdgeInsets.fromLTRB(20, 20, 20, 32),
                children: [
                  Center(
                    child: Container(
                      width: 40,
                      height: 4,
                      margin: const EdgeInsets.only(bottom: 16),
                      decoration: BoxDecoration(
                        color: _isDarkCtx(context) ? Colors.white24 : Colors.black26,
                        borderRadius: BorderRadius.circular(2),
                      ),
                    ),
                  ),
                  Text(
                    AppL.editExercise,
                    style: TextStyle(
                      color: accent,
                      fontWeight: FontWeight.bold,
                      fontSize: 16,
                    ),
                  ),
                  const SizedBox(height: 16),
                  TextField(
                    controller: nameCtrl,
                    style: TextStyle(color: _isDarkCtx(context) ? Colors.white : Colors.black87),
                    decoration: InputDecoration(
                      labelText: AppL.exerciseName,
                      labelStyle: TextStyle(color: _isDarkCtx(context) ? Colors.white54 : Colors.black54),
                      filled: true,
                      fillColor: Colors.black26,
                      border: OutlineInputBorder(
                        borderRadius: BorderRadius.circular(12),
                        borderSide: BorderSide.none,
                      ),
                    ),
                  ),
                  const SizedBox(height: 8),
                  OutlinedButton.icon(
                    onPressed: () => _apriArchivioEsercizi(ctx, setS, (ex) {
                      nameCtrl.text = ex.name;
                      setS(() => selectedExInfo = ex);
                    }),
                    icon: const Icon(Icons.library_books_rounded, size: 18),
                    label: Text(AppL.browseArchive),
                    style: OutlinedButton.styleFrom(
                      foregroundColor: accent,
                      side: BorderSide(color: accent.withAlpha(80)),
                      shape: RoundedRectangleBorder(
                        borderRadius: BorderRadius.circular(10),
                      ),
                    ),
                  ),
                  const SizedBox(height: 12),
                  Row(
                    children: [
                      Expanded(
                        child: TextField(
                          controller: setsCtrl,
                          keyboardType: TextInputType.number,
                          style: TextStyle(color: _isDarkCtx(context) ? Colors.white : Colors.black87),
                          decoration: InputDecoration(
                            labelText: AppL.sets,
                            labelStyle: TextStyle(color: _isDarkCtx(context) ? Colors.white54 : Colors.black54),
                            filled: true,
                            fillColor: Colors.black26,
                            border: OutlineInputBorder(
                              borderRadius: BorderRadius.circular(12),
                              borderSide: BorderSide.none,
                            ),
                          ),
                          onChanged: updateSets,
                        ),
                      ),
                      const SizedBox(width: 12),
                      Expanded(
                        child: TextField(
                          controller: recoveryCtrl,
                          keyboardType: TextInputType.number,
                          style: TextStyle(color: _isDarkCtx(context) ? Colors.white : Colors.black87),
                          decoration: InputDecoration(
                            labelText: AppL.recovery,
                            labelStyle: TextStyle(color: _isDarkCtx(context) ? Colors.white54 : Colors.black54),
                            filled: true,
                            fillColor: Colors.black26,
                            border: OutlineInputBorder(
                              borderRadius: BorderRadius.circular(12),
                              borderSide: BorderSide.none,
                            ),
                          ),
                        ),
                      ),
                      const SizedBox(width: 12),
                      Expanded(
                        child: TextField(
                          controller: pausaCtrl,
                          keyboardType: TextInputType.number,
                          style: TextStyle(color: _isDarkCtx(context) ? Colors.white : Colors.black87),
                          decoration: InputDecoration(
                            labelText: AppL.pauseSec,
                            labelStyle: TextStyle(color: _isDarkCtx(context) ? Colors.white54 : Colors.black54),
                            filled: true,
                            fillColor: Colors.black26,
                            border: OutlineInputBorder(
                              borderRadius: BorderRadius.circular(12),
                              borderSide: BorderSide.none,
                            ),
                          ),
                        ),
                      ),
                    ],
                  ),
                  const SizedBox(height: 12),
                  Text(
                    AppL.repsPerSet,
                    style: TextStyle(color: _isDarkCtx(context) ? Colors.white54 : Colors.black54, fontSize: 12),
                  ),
                  const SizedBox(height: 6),
                  Wrap(
                    spacing: 8,
                    runSpacing: 8,
                    children: List.generate(
                      currentSets,
                      (i) => SizedBox(
                        width: 58,
                        child: TextField(
                          controller: repsCtrls[i],
                          keyboardType: TextInputType.number,
                          textAlign: TextAlign.center,
                          style: TextStyle(
                            color: _isDarkCtx(context) ? Colors.white : Colors.black87,
                            fontSize: 13,
                          ),
                          decoration: InputDecoration(
                            labelText: 'S${i + 1}',
                            labelStyle: TextStyle(
                              color: _isDarkCtx(context) ? Colors.white38 : Colors.black38,
                              fontSize: 11,
                            ),
                            filled: true,
                            fillColor: Colors.black26,
                            contentPadding: const EdgeInsets.symmetric(
                              vertical: 8,
                            ),
                            border: OutlineInputBorder(
                              borderRadius: BorderRadius.circular(10),
                              borderSide: BorderSide.none,
                            ),
                          ),
                        ),
                      ),
                    ),
                  ),
                  const SizedBox(height: 16),
                  TextField(
                    controller: noteCtrl,
                    maxLines: 3,
                    style: TextStyle(color: _isDarkCtx(context) ? Colors.white : Colors.black87),
                    decoration: InputDecoration(
                      labelText: AppL.notes,
                      labelStyle: TextStyle(color: _isDarkCtx(context) ? Colors.white54 : Colors.black54),
                      filled: true,
                      fillColor: Colors.black26,
                      border: OutlineInputBorder(
                        borderRadius: BorderRadius.circular(12),
                        borderSide: BorderSide.none,
                      ),
                    ),
                  ),
                  const SizedBox(height: 20),
                  SizedBox(
                    width: double.infinity,
                    child: ElevatedButton(
                      onPressed: () {
                        final name = nameCtrl.text.trim();
                        if (name.isEmpty) return;
                        final sets = (int.tryParse(setsCtrl.text) ?? 3).clamp(
                          1,
                          20,
                        );
                        final repsList = repsCtrls
                            .map((c) => int.tryParse(c.text) ?? 10)
                            .toList();
                        final recovery = int.tryParse(recoveryCtrl.text) ?? 90;
                        final pausa = int.tryParse(pausaCtrl.text) ?? 120;
                        final newEx = ExerciseConfig(
                          name: name,
                          targetSets: sets,
                          repsList: repsList,
                          recoveryTime: recovery,
                          interExercisePause: pausa,
                          notePT: noteCtrl.text.trim(),
                          noteCliente: orig.noteCliente,
                          supersetGroup: supersetGroup,
                          gifFilename:
                              selectedExInfo?.gifFilename ?? orig.gifFilename,
                          useQuarterStep: orig.useQuarterStep,
                        );
                        Navigator.pop(c);
                        setState(() => _days[dayIdx].exercises[exIdx] = newEx);
                        _save();
                      },
                      child: Text(
                        AppL.save,
                        style: const TextStyle(
                          fontWeight: FontWeight.bold,
                          fontSize: 16,
                        ),
                      ),
                    ),
                  ),
                ],
              ),
            ),
          );
        },
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final accent = appAccentNotifier.value;
    return Scaffold(
      backgroundColor: _isDarkCtx(context) ? const Color(0xFF0A0A0A) : Colors.white,
      appBar: AppBar(
        title: Text(AppL.mySchedule),
        leading: IconButton(
          icon: Icon(Icons.arrow_back_ios_new, color: _isDarkCtx(context) ? Colors.white : Colors.black87),
          onPressed: () => Navigator.pop(context),
        ),
        actions: [
          TextButton(
            onPressed: () async {
              await _save();
              if (mounted) Navigator.pop(context);
            },
            child: Text(
              AppL.save,
              style: TextStyle(color: accent, fontWeight: FontWeight.bold),
            ),
          ),
        ],
      ),
      floatingActionButton: Row(
        mainAxisSize: MainAxisSize.min,
        children: [
          FloatingActionButton.extended(
            heroTag: 'templates_fab',
            onPressed: _mostraTemplateDialog,
            backgroundColor: _isDarkCtx(context) ? const Color(0xFF2C2C2E) : const Color(0xFFF2F2F7),
            foregroundColor: Colors.amber,
            icon: const Icon(Icons.auto_awesome_rounded),
            label: Text(AppL.templates),
          ),
          const SizedBox(width: 12),
          FloatingActionButton.extended(
            heroTag: 'add_day_fab',
            onPressed: _aggiungiGiorno,
            backgroundColor: accent,
            foregroundColor: Colors.black,
            icon: const Icon(Icons.add),
            label: Text(AppL.day),
          ),
        ],
      ),
      body: _loading
          ? const Center(child: CircularProgressIndicator())
          : _days.isEmpty
          ? Center(
              child: Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  Icon(
                    Icons.fitness_center_rounded,
                    color: accent.withAlpha(60),
                    size: 64,
                  ),
                  const SizedBox(height: 16),
                  Text(
                    AppL.noScheduleYet,
                    style: TextStyle(color: _isDarkCtx(context) ? Colors.white38 : Colors.black38, fontSize: 16),
                  ),
                  const SizedBox(height: 24),
                  // Speech bubble hint
                  GestureDetector(
                    onTap: _mostraTemplateDialog,
                    child: Container(
                      margin: const EdgeInsets.symmetric(horizontal: 32),
                      padding: const EdgeInsets.symmetric(
                        horizontal: 20,
                        vertical: 14,
                      ),
                      decoration: BoxDecoration(
                        color: accent.withAlpha(20),
