                  Expanded(child: Center(child: _buildBoxEsercizioCompletato()))
                else
                  Expanded(
                    child: _DrumPickers(
                      key: ValueKey('drum_$exI'),
                      initialKg: lastW <= 0 ? 20.0 : lastW,
                      initialReps: targetR,
                      suggerisciAumento:
                          suggerisciAumento && _showWeightSuggestion,
                      useQuarterStep: _usesQuarterStepForExercise(ex, lastW),
